function minNumberOfFrogs(croakOfFrogs) {
  const order = 'croak';
  const count = [0, 0, 0, 0, 0];
  let active = 0;
  let frogs = 0;

  for (const letter of croakOfFrogs) {
    const stage = order.indexOf(letter);
    count[stage]++;
    if (stage === 0) {
      active++;
      frogs = Math.max(frogs, active);
      continue;
    }
    if (count[stage] > count[stage - 1]) {
      return -1;
    }
    if (stage === 4) {
      active--;
    }
  }

  if (active !== 0) {
    return -1;
  }
  return frogs;
}

