function minNumberOfFrogs(croakOfFrogs) {
  // Simulate frogs one by one: each frog remembers which letter it needs next (0 means idle, ready for 'c').
  const word = 'croak';
  const needs = [];
  for (const ch of croakOfFrogs) {
    const pos = word.indexOf(ch);
    let index = needs.indexOf(pos);
    if (index === -1) {
      if (pos !== 0) return -1;
      needs.push(0);
      index = needs.length - 1;
    }
    needs[index] = (pos + 1) % 5;
  }
  if (needs.some(n => n !== 0)) return -1;
  return needs.length;
}

