function generate(rand, size) {
  const word = 'croak';
  const croaks = size === 'large' ? 1500 + Math.floor(rand() * 501) : 1 + Math.floor(rand() * 4);
  const startBias = rand();
  const progress = [];
  let started = 0;
  let out = '';
  while (started < croaks || progress.length) {
    if (started < croaks && (progress.length === 0 || rand() < startBias)) {
      progress.push(0);
      started++;
    }
    const pick = Math.floor(rand() * progress.length);
    out += word[progress[pick]];
    progress[pick]++;
    if (progress[pick] === 5) progress.splice(pick, 1);
  }
  // Sometimes break the string so -1 answers are covered too.
  if (rand() < (size === 'large' ? 0.35 : 0.5)) {
    const chars = out.split('');
    const kind = Math.floor(rand() * 4);
    const at = Math.floor(rand() * chars.length);
    if (kind === 0) chars[at] = word[Math.floor(rand() * 5)];
    else if (kind === 1 && chars.length > 1) chars.splice(at, 1);
    else if (kind === 2) { const other = Math.floor(rand() * chars.length); [chars[at], chars[other]] = [chars[other], chars[at]]; }
    else chars.splice(at, 0, word[Math.floor(rand() * 5)]);
    out = chars.join('').slice(0, 10000);
  }
  return [out];
}
